using System;
using System.Collections.Generic;
using System.Globalization;
using System.Text;

namespace Gallop
{
    // Generated from the original stage prefab MirrorReflection MonoBehaviours.
    // The prefab script is unavailable at runtime, so these authored fields are
    // restored when the receiver component is auto-attached.
    internal static class MirrorReflectionPrefabTable
    {
        const string Part0 = "";
        const string Part1 = "";
        const string Part2 = "";
        const string Part3 = "";
        const string Part4 = "";
        const string Part5 = "";
        const string Part6 = "";
        const string Part7 = "";
        const string Part8 = "";
        const string Part9 = "";
        const string Part10 = "";
        const string Part11 = "";
        const string Part12 = "";
        const string Part13 = "";
        const string Part14 = "";
        const string Part15 = "";
        const string Part16 = "";
        const string Part17 = "";
        const string Part18 = "";
        const string Part19 = "";
        const string Part20 = "";
        const string Part21 = "";
        public sealed class Row
        {
            public int TextureSize, Direction, Layers;
            public float Clip, Rate, Scale;
            public bool UseBackground, UseScale;
            public float[] DistTile, DistPower, ReflectionColor, Background;
        }

        static Dictionary<string, Row> rows;

        static float[] Vec(string value)
        {
            string[] parts = value.Split(',');
            float[] result = new float[parts.Length];
            for (int i = 0; i < parts.Length; i++)
                result[i] = float.Parse(parts[i], CultureInfo.InvariantCulture);
            return result;
        }

        public static bool TryGet(string stage, string objectName, out Row row)
        {
            row = null;
            if (string.IsNullOrEmpty(stage) || string.IsNullOrEmpty(objectName)) return false;
            if (rows == null)
            {
                var text = new StringBuilder();
                text.Append(Part0);
                text.Append(Part1);
                text.Append(Part2);
                text.Append(Part3);
                text.Append(Part4);
                text.Append(Part5);
                text.Append(Part6);
                text.Append(Part7);
                text.Append(Part8);
                text.Append(Part9);
                text.Append(Part10);
                text.Append(Part11);
                text.Append(Part12);
                text.Append(Part13);
                text.Append(Part14);
                text.Append(Part15);
                text.Append(Part16);
                text.Append(Part17);
                text.Append(Part18);
                text.Append(Part19);
                text.Append(Part20);
                text.Append(Part21);
                string csv = Encoding.UTF8.GetString(Convert.FromBase64String(text.ToString()));
                rows = new Dictionary<string, Row>(StringComparer.OrdinalIgnoreCase);
                foreach (string source in csv.Split('\n'))
                {
                    if (string.IsNullOrEmpty(source)) continue;
                    string[] f = source.Split('|');
                    if (f.Length < 14) continue;
                    var r = new Row
                    {
                        TextureSize = int.Parse(f[2], CultureInfo.InvariantCulture),
                        Clip = float.Parse(f[3], CultureInfo.InvariantCulture),
                        Rate = float.Parse(f[4], CultureInfo.InvariantCulture),
                        DistTile = Vec(f[5]), DistPower = Vec(f[6]),
                        Direction = int.Parse(f[7], CultureInfo.InvariantCulture),
                        ReflectionColor = Vec(f[8]), Background = Vec(f[9]),
                        UseBackground = f[10] == "1", UseScale = f[11] == "1",
                        Scale = float.Parse(f[12], CultureInfo.InvariantCulture),
                        Layers = int.Parse(f[13], CultureInfo.InvariantCulture)
                    };
                    rows[f[0] + "/" + f[1]] = r;
                }
            }
            return rows.TryGetValue(stage + "/" + objectName, out row);
        }

        public static bool HasStage(string stage)
        {
            if (string.IsNullOrEmpty(stage)) return false;
            if (rows == null) TryGet(stage, "__probe__", out _);
            foreach (string key in rows.Keys)
                if (key.StartsWith(stage + "/", StringComparison.Ordinal)) return true;
            return false;
        }
    }
}
